head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusFlow]<br/>GridView 컴포넌트의 포커스 이동 흐름을 설정합니다.",
    "validation" : [
        "'default' (default) 설정 시 상/하/좌/우 의 마지막 Cell 에서 이전/다음 Row 또는 Column 의 Cell 로 포커스가 이동하지 않습니다.",
        "'linear' 설정 시 상/하/좌/우 의 마지막 Cell 에서 이전/다음 Row 또는 Column 의 Cell 로 포커스가 이동합니다.",
        "senseReader=true 이면 focusFlow 는 'linear' 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        focusMove: true,
        focusFlow: con_focusFlow.getText(),
        senseReader: con_senseReader.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oncellclick"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList, eList);

    // 키보드 위/아래 방향키, Tab 키 입력 후 엔진의 포커스 이동 결과를 출력 (focusFlow 동작 검증용)
    let gridEl = document.getElementById('mf_target1');
    if (gridEl) {
        gridEl.addEventListener('keyup', function (e) {
            if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown' && e.key !== 'Tab') return;
            // 엔진 keydown 처리 완료 후 셀 이동 결과 출력            
                let row = target1.getFocusedRowIndex();
                let col = target1.getFocusedColumnIndex();
                wf_body_bottom.getObj("scwin").setReturnValue("=====keyup : " + e.key + (e.shiftKey ? " (shift)" : "") + "=====");
                wf_body_bottom.getObj("scwin").setReturnValue("focused rowIndex : " + row + ", colIndex : " + col);            
        });
    }
}



scwin.target1_oncellclick = function (rowIndex, colIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("clicked rowIndex : " + rowIndex + ", colIndex : " + colIndex);
}
